import java.io.*;

public class Main {
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = System.in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    static int readInt() throws IOException {
        int c = readByte();
        while (c != -1 && c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean negative = c == '-';
        if (negative) c = readByte();
        int x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return negative ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        int n = readInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = readInt();
        int k = readInt();
        // XOR difference array: [l, r] flips the parity of 0-based positions l-1 .. r-1.
        byte[] flip = new byte[n + 1];
        for (int i = 0; i < k; i++) {
            int l = readInt(), r = readInt();
            flip[l - 1] ^= 1;
            flip[r] ^= 1;
        }
        StringBuilder sb = new StringBuilder(n * 12);
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur ^= flip[i]; // prefix XOR = parity of covering updates
            if (i > 0) sb.append(' ');
            sb.append(cur != 0 ? -a[i] : a[i]);
        }
        sb.append('\n');
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        out.write(sb.toString());
        out.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	readInt := func() int {
		c, err := reader.ReadByte()
		for err == nil && c != '-' && (c < '0' || c > '9') {
			c, err = reader.ReadByte()
		}
		negative := c == '-'
		if negative {
			c, err = reader.ReadByte()
		}
		x := 0
		for err == nil && c >= '0' && c <= '9' {
			x = x*10 + int(c-'0')
			c, err = reader.ReadByte()
		}
		if negative {
			return -x
		}
		return x
	}
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	k := readInt()
	// XOR difference array: [l, r] flips the parity of 0-based positions l-1 .. r-1.
	flip := make([]byte, n+1)
	for i := 0; i < k; i++ {
		l, r := readInt(), readInt()
		flip[l-1] ^= 1
		flip[r] ^= 1
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	var cur byte
	num := make([]byte, 0, 24)
	for i := 0; i < n; i++ {
		cur ^= flip[i] // prefix XOR = parity of covering updates
		v := a[i]
		if cur != 0 {
			v = -v
		}
		if i > 0 {
			w.WriteByte(' ')
		}
		num = strconv.AppendInt(num[:0], int64(v), 10)
		w.Write(num)
	}
	w.WriteByte('\n')
}
